public struct FfiConverterTypeParamKind: FfiConverterRustBuffer {
    typealias SwiftType = ParamKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ParamKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .wallLength
        
        case 2: return .wallThickness
        
        case 3: return .wallHeight
        
        case 4: return .openingOffset
        
        case 5: return .openingWidth
        
        case 6: return .openingHeight
        
        case 7: return .openingSillHeight
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ParamKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .wallLength:
            writeInt(&buf, Int32(1))
        
        
        case .wallThickness:
            writeInt(&buf, Int32(2))
        
        
        case .wallHeight:
            writeInt(&buf, Int32(3))
        
        
        case .openingOffset:
            writeInt(&buf, Int32(4))
        
        
        case .openingWidth:
            writeInt(&buf, Int32(5))
        
        
        case .openingHeight:
            writeInt(&buf, Int32(6))
        
        
        case .openingSillHeight:
            writeInt(&buf, Int32(7))
        
        }
    }
}


