fileprivate struct FfiConverterSequenceTypeParamValue: FfiConverterRustBuffer {
    typealias SwiftType = [ParamValue]

    public static func write(_ value: [ParamValue], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeParamValue.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [ParamValue] {
        let len: Int32 = try readInt(&buf)
        var seq = [ParamValue]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeParamValue.read(from: &buf))
        }
        return seq
    }
}

